import itertools

def is_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for i in range(n):
        for j in adj[i]:
            if j > i:
                if adj[i].intersection(adj[j]):
                    return False
    return True

def is_maximal(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for i in range(n):
        for j in range(i + 1, n):
            if j not in adj[i]:
                # Check if adding (i, j) creates a triangle
                if not adj[i].intersection(adj[j]):
                    return False
    return True

