# Let's just search for a complete bipartite graph K_3,3 that includes (3, 5)
# Partition the vertices into two sets A and B of size 3.
# 3 and 5 must be in different sets.
for A in itertools.combinations(range(n), 3):
    if 3 in A and 5 not in A:
        B = [x for x in range(n) if x not in A]
        edges = []
        for a in A:
            for b in B:
                edges.append((min(a, b), max(a, b)))
        edges.sort()
        if is_triangle_free(edges, n) and is_maximal(edges, n):
